import { AppToggle } from '@/registry/ndeko/components/navbar/_parts/app-toggle';
import { TeamSwitcher } from '@/registry/ndeko/components/navbar/_parts/team-switcher';
import { SparklesIcon, UploadIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

const TEAMS = ['Acme Inc.', 'Lumen Labs', 'Junon'];

export default function Navbar18() {
  return (
    <header className='hairline-b border-border px-4 md:px-6'>
      <div className='flex h-16 items-center justify-between gap-4'>
        <div className='flex flex-1 items-center gap-2'>
          <TeamSwitcher teams={TEAMS} defaultTeam={TEAMS[0]} />
        </div>
        <div className='max-sm:hidden'>
          <AppToggle />
        </div>
        <div className='flex flex-1 items-center justify-end gap-2'>
          <Button variant='ghost' className='max-sm:aspect-square max-sm:px-0'>
            <UploadIcon className='opacity-60' />
            <span className='max-sm:sr-only'>Export</span>
          </Button>
          <Button className='max-sm:aspect-square max-sm:px-0'>
            <SparklesIcon className='opacity-60' />
            <span className='max-sm:sr-only'>Upgrade</span>
          </Button>
        </div>
      </div>
    </header>
  );
}

import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

function AppToggle() {
  return (
    <Tabs defaultValue='wireframe'>
      <TabsList variant='segmented' aria-label='View'>
        <TabsTab value='sitemap'>Sitemap</TabsTab>
        <TabsTab value='wireframe'>Wireframe</TabsTab>
      </TabsList>
    </Tabs>
  );
}

export { AppToggle };

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };
const EXIT_TRANSITION: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const LABEL_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)', transition: EXIT_TRANSITION },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT_TRANSITION },
};

function labelVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return LABEL_VARIANTS;
}

type MorphingLabelProps = {
  value: string;
  className?: string;
  children: React.ReactNode;
};

function MorphingLabel({ value, className, children }: MorphingLabelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const labelVariants = labelVariantsOf(shouldReduceMotion);

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={value}
          className={cn('flex whitespace-nowrap', className)}
          variants={labelVariants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

export { MorphingLabel };

'use client';

import { useState } from 'react';

import { MorphingLabel } from '@/registry/ndeko/components/navbar/_parts/morphing-label';
import { ChevronsUpDownIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

const GEM_STYLE = { '--gem': 'var(--primary)' } as React.CSSProperties;

function initialOf(team: string) {
  const firstLetter = team.charAt(0);
  return firstLetter.toUpperCase();
}

function TeamMark({ team }: { team: string }) {
  return (
    <span
      aria-hidden='true'
      style={GEM_STYLE}
      className='gem-plate flex size-6 shrink-0 items-center justify-center rounded-md text-xs font-semibold'
    >
      {initialOf(team)}
    </span>
  );
}

type TeamSwitcherProps = {
  teams: string[];
  defaultTeam: string;
};

function TeamSwitcher({ teams, defaultTeam }: TeamSwitcherProps) {
  const [selectedTeam, setSelectedTeam] = useState(defaultTeam);

  function selectTeam(team: string) {
    setSelectedTeam(team);
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={<Button variant='ghost' className='gap-2 px-1.5' />}
      >
        <TeamMark team={selectedTeam} />
        <MorphingLabel value={selectedTeam}>{selectedTeam}</MorphingLabel>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5' />
      </DropdownMenuTrigger>
      <DropdownMenuContent>
        <DropdownMenuRadioGroup value={selectedTeam} onValueChange={selectTeam}>
          {teams.map((team) => (
            <DropdownMenuRadioItem key={team} value={team} closeOnClick>
              <TeamMark team={team} />
              {team}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export { TeamSwitcher };
